from google.cloud import speech

def get_speech_client():
    return speech.SpeechClient()

def get_streaming_config(sample_rate_hertz, language_code, interim_results=True, enable_automatic_punctuation=False):
    recognition_config = speech.RecognitionConfig(
        encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
        sample_rate_hertz=sample_rate_hertz,
        language_code=language_code,
        enable_automatic_punctuation=enable_automatic_punctuation,
    )
    return speech.StreamingRecognitionConfig(config=recognition_config, interim_results=interim_results)

import dataclasses

@dataclasses.dataclass
class SpeechRecognitionRequest:
    audio_chunks: list[bytes]
    sample_rate_hz: int
    language_code: str
    enable_automatic_punctuation: bool = False

def normalize_transcript(transcript: str) -> str:
    return transcript.strip()

from speech_client import get_speech_client, get_streaming_config
from speech_models import SpeechRecognitionRequest
from google.cloud import speech


async def stream_chunks(request: SpeechRecognitionRequest):
    client = get_speech_client()
    streaming_config = get_streaming_config(
        request.sample_rate_hz,
        request.language_code,
        enable_automatic_punctuation=request.enable_automatic_punctuation,
    )

    def generate_requests():
        for chunk in request.audio_chunks:
            yield speech.StreamingRecognizeRequest(audio_content=chunk)

    responses = client.streaming_recognize(
        config=streaming_config, requests=generate_requests()
    )

    for response in responses:
        for result in response.results:
            if result.alternatives:
                yield {"text": result.alternatives[0].transcript, "is_final": result.is_final}

from speech_client import get_speech_client, get_streaming_config
from speech_models import SpeechRecognitionRequest, normalize_transcript
from google.cloud import speech


def handle_partial_results(request: SpeechRecognitionRequest):
    client = get_speech_client()
    streaming_config = get_streaming_config(
        request.sample_rate_hz,
        request.language_code,
        interim_results=True,
        enable_automatic_punctuation=request.enable_automatic_punctuation,
    )

    def generate_requests():
        for chunk in request.audio_chunks:
            yield speech.StreamingRecognizeRequest(audio_content=chunk)

    responses = client.streaming_recognize(
        config=streaming_config, requests=generate_requests()
    )

    for response in responses:
        for result in response.results:
            if result.alternatives:
                transcript = normalize_transcript(result.alternatives[0].transcript)
                yield {"text": transcript, "is_final": result.is_final, "stability": result.stability}

